package com.pharmapack.qms.master; import jakarta.persistence.*; import lombok.*; import java.time.LocalDate; @Entity @Table(name="equipment") @Getter @Setter @NoArgsConstructor public class Equipment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(name="equipment_code",nullable=false,unique=true) String equipmentCode; @Column(name="equipment_name",nullable=false) String equipmentName; String equipmentType; String status="AVAILABLE"; LocalDate calibrationDueDate; }